def f(g):
    H,W=len(g),len(g[0])
    # find bar: maximal rectangle of nonzero rows contiguous; use largest zero-free band heuristic -> find colors present
    from collections import Counter,defaultdict
    cnt=Counter(v for row in g for v in row)
    colors={k:v for k,v in cnt.items() if k!=0}
    # locate each color's bounding box
    boxes=defaultdict(list)
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v: boxes[v].append((r,c))
    info={}
    for col,cells in boxes.items():
        rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
        info[col]=(min(rs),max(rs),min(cs),max(cs))
    # bar colors: those whose bbox is a flat line (height==width and full rectangle) and tall/thin vs shape
    # identify "shapes": components of >1 cell with area >= some; bar: cells count == bbox area and aspect ~1:1 thin
    def comps(grid):
        H,W=len(grid),len(grid[0]); seen=[[False]*W for _ in range(H)]; out=[]
        for r in range(H):
            for c in range(W):
                if grid[r][c]!=0 and not seen[r][c]:
                    col=grid[r][c]; q=[[r,c]]; cells=[]; seen[r][c]=True
                    while q:
                        y,x=q.pop(); cells.append((y,x))
                        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and grid[ny][nx]==col:
                                seen[ny][nx]=True; q.append((ny,nx))
                    out.append((col,cells))
        return out
    cc=comps(g)
    shapes={col:cells for col,cells in cc if len(cells)>3}
    # bars: components with len==bbox area (solid rectangle) and small
    bars=[(col,cells) for col,cells in cc if len(cells)==(max([p[0] for p in cells])-min([p[0] for p in cells])+1)*(max([p[1] for p in cells])-min([p[1] for p in cells])+1) and len(cells)<=12]
    # determine stacking order from bars: collect bar colors in reading order
    bcols=[]
    for col,cells in sorted(cc,key=lambda t:(min(p[0] for p in t[1]),min(p[1] for p in t[1]))):
        if len(cells)==(max(p[0] for p in cells)-min(p[0] for p in cells)+1)*(max(p[1] for p in cells)-min(p[1] for p in cells)+1) and len(cells)<=12:
            bcols.append(col)
    # build output: copy each shape; for each bar color pair (b_i,b_{i+1}): if shape of color b_{i+1} exists,
    # place a copy of it recolored to b_i directly above (if free) else below the shape; remove bars
    out=[row[:] for row in g]
    for i in range(len(bcols)-1):
        c1,c2=bcols[i],bcols[i+1]
        if c2 not in shapes: continue
        rs0,cs0,rss0,_=info[c2]
        h0=rss0-rs0+1; w0=max(p[1] for p in shapes[c2])-min(p[1] for p in shapes[c2])+1
        # candidate above: rows rs0-1-h0 .. rs0-1
        top=rs0-1-h0
        ok=True
        for r in range(top,top+h0):
            for c in range(min(p[1] for p in shapes[c2]),max(p[1] for p in shapes[c2])+1):
                if out[r][c]: ok=False
        if ok:
            for r,c in shapes[c2]: out[r-top+top][c]=c1 if False else None
            # paint copy
            tmpl=[(r-cs) for r,c in shapes[c2]]
            for (rr,ccx) in shapes[c2]:
                rr2=rr-(rs0)-(top-rs0)
                out[rr2][ccx]=c1
    for col,cells in cc:
        if len(cells)==(max(p[0] for p in cells)-min(p[0] for p in cells)+1)*(max(p[1] for p in cells)-min(p[1] for p in cells)+1) and len(cells)<=12:
            for r,c in cells: out[r][c]=0
    return out
